<script setup lang="ts">import { computed } from "vue"
import type { CalloutBlockProps } from "@/types/blocks"
import { scv, cx } from "css-variants"
import { useRC } from "@/composables"
import BlockViewRenderer from "../BlockViewRenderer.vue"/* region Props */export interface CalloutBlockRendererProps extends CalloutBlockProps {  rc?: {    root?: string    icon?: string  }}const {  variant = "info",  children = [],  to,  target,  rc: rcProp} = defineProps<CalloutBlockRendererProps>()const { rc } = useRC("CalloutBlockRenderer", rcProp)/* endregion *//* region Styles */const calloutBlockRendererStyles = scv({  slots: {    root: "border rounded-xl p-4 my-4 flex items-start gap-3",    iconClass: "size-5 shrink-0 mt-0.5",    content: "flex-1 min-w-0 text-sm"  }})const styles = computed(() => {  const resolved = calloutBlockRendererStyles()  const result: Record<string, string> = {}  for (const [slot, value] of Object.entries(resolved)) {    result[slot] = cx(value, (rc.value as Record<string, string>)[slot])  }  return result as {    root: string    iconClass: string    content: string  }})/* endregion *//* region State */const variantConfigs: Record<string, { icon: string; classes: string; label: string }> = {  info: {    icon: "i-lucide-info",    classes:      "bg-blue-50/50 dark:bg-blue-950/10 border-blue-200 dark:border-blue-900/50 text-blue-800 dark:text-blue-200",    label: "Info"  },  success: {    icon: "i-lucide-check-circle",    classes:      "bg-green-50/50 dark:bg-green-950/10 border-green-200 dark:border-green-900/50 text-green-800 dark:text-green-200",    label: "Success"  },  warning: {    icon: "i-lucide-alert-triangle",    classes:      "bg-yellow-50/50 dark:bg-yellow-950/10 border-yellow-200 dark:border-yellow-900/50 text-yellow-800 dark:text-yellow-200",    label: "Warning"  },  error: {    icon: "i-lucide-alert-octagon",    classes:      "bg-red-50/50 dark:bg-red-950/10 border-red-200 dark:border-red-900/50 text-red-800 dark:text-red-200",    label: "Error"  },  commentary: {    icon: "i-lucide-message-square",    classes:      "bg-purple-50/50 dark:bg-purple-950/10 border-purple-200 dark:border-purple-900/50 text-purple-800 dark:text-purple-200",    label: "Commentary"  },  ideation: {    icon: "i-lucide-lightbulb",    classes:      "bg-amber-50/50 dark:bg-amber-950/10 border-amber-200 dark:border-amber-900/50 text-amber-800 dark:text-amber-200",    label: "Ideation"  },  source: {    icon: "i-lucide-code",    classes:      "bg-indigo-50/50 dark:bg-indigo-950/10 border-indigo-200 dark:border-indigo-900/50 text-indigo-800 dark:text-indigo-200",    label: "Source"  }}const currentConfig = computed(() => {  return variantConfigs[variant] || variantConfigs.info})const isLink = computed(() => !!to)const Tag = computed(() => (to ? "a" : "div"))/* endregion */defineOptions({  name: "CalloutBlockRenderer"})</script><template>  <component :is="Tag" :href="to" :target="target" :class="[styles.root, currentConfig.classes]">    <span :class="[currentConfig.icon, styles.iconClass]" aria-hidden="true" />    <div :class="styles.content">      <BlockViewRenderer :blocks="children" />    </div>  </component></template>